'use strict';
courierNav.splice(0,courierNav.length,['home','Bosh ekran','chart'],['offers','Yangi buyurtmalar','bag'],['active','Faol yetkazma','pin'],['route','Xarita va yo‘nalish','pin'],['earnings','Daromad va hisob-kitob','wallet'],['work','Ish jadvali','calendar'],['history','Yetkazmalar tarixi','orders'],['results','Natijalar','star'],['help','Yordam va muammolar','help'],['profile','Profil va sozlamalar','settings']);
let courierHistoryStatus='all',courierHistoryQuery='',courierMinFee='',courierMaxFee='',courierFromDate='',courierToDate='';
const workLabels={working:'Ishdaman',break:'Tanaffusdaman',offline:'Ishda emasman'};
const phaseLabels={to_restaurant:'Restoranga yo‘ldaman',at_restaurant:'Restorandaman',to_customer:'Buyurtmani oldim',at_customer:'Mijozga yetib keldim',delivered:'Yetkazildi',returned:'Restoranga qaytarildi'};
const issueTypes={restaurant:'Restoran kechikishi',customer:'Mijoz javob bermasligi',address:'Noto‘g‘ri manzil',vehicle:'Transport muammosi',damaged:'Shikastlangan buyurtma',other:'Boshqa muammo'};
const terminalLabels={delivered:'Yakunlangan',cancelled:'Bekor qilingan',returned:'Restoranga qaytarilgan',released:'Taklifga qaytarilgan',declined:'Rad etilgan taklif'};
function courierWorkButtons(){const status=courierWork(courierPerson());return `<div class="work-buttons">${Object.entries(workLabels).map(([id,label])=>courierButton(label,'work-'+id,'',status===id?'primary':'')).join('')}</div>`;}
function courierPhone(phone,label){return /^[+0-9 ()-]{9,25}$/.test(phone||'')?`<a class="btn" href="tel:${esc(phone.replace(/[^+0-9]/g,''))}">${icon('phone')}${label}</a>`:`<span class="metric-note">${label}: telefon kiritilmagan</span>`;}
function courierDirection(address,label,origin=''){if(!address)return '';return `<a class="btn" href="https://www.google.com/maps/dir/?api=1&destination=${encodeURIComponent(address)}${origin?'&origin='+encodeURIComponent(origin):''}" target="_blank" rel="noopener noreferrer">${icon('pin')}${label}</a>`;}
function courierDetails(o){return `<div class="address-details">${[['Kirish eshigi',o.deliveryEntrance],['Qavat',o.deliveryFloor],['Mo‘ljal',o.deliveryLandmark],['Paketlar soni',o.packageCount]].map(([t,v])=>`<div><span>${t}</span><strong>${v!==undefined&&v!==''?esc(v):'Kiritilmagan'}</strong></div>`).join('')}</div>`;}
function courierTimeline(o){const keys=['to_restaurant','at_restaurant','to_customer','at_customer','delivered'],index=keys.indexOf(courierPhase(o));return `<ol class="courier-timeline">${keys.map((phase,i)=>`<li class="${i<=index?'done':''}"><b>${i+1}</b><span>${phaseLabels[phase]}</span></li>`).join('')}</ol>`;}
courierCard=function(o,mode){const b=courierBranchInfo(o.branch),owned=o.delivery?.courierId===courierId,phase=courierPhase(o),fee=o.delivery?.fee??o.deliveryFee,eligible=courierPerson()?.online&&!courierActiveOrders(courierState,courierId).length&&deliveryReady(o);const next={to_restaurant:['Restorandaman','arrive-restaurant'],at_restaurant:['Buyurtmani oldim','confirm-pickup'],to_customer:['Mijozga yetib keldim','arrive-customer'],at_customer:['Yetkazildi','confirm-deliver']}[phase];return `<article class="courier-card"><div class="order-head"><div><strong>#${esc(o.id.slice(0,12))}</strong> ${o.courierDemo?'<span class="tag">Sinov</span>':''}<div>${deliveryBadge(o)||'<span class="tag success">Olib ketishga tayyor</span>'}</div></div><div class="reward">${Number.isFinite(fee)?money(fee):'—'} <small>so‘m</small></div></div><div class="route-stops"><div class="route-stop"><span class="stop-marker">${icon('bag')}</span><div><small>RESTORANDAN OLISH</small><strong>${esc(b?.name||'Noma’lum filial')}</strong><p class="metric-note">${esc(b?.address||'Manzil kiritilmagan')}</p></div></div><div class="route-stop"><span class="stop-marker">${icon('pin')}</span><div><small>YETKAZISH MANZILI</small><strong>${esc(o.deliveryAddress||'Manzil kiritilmagan')}</strong></div></div></div><div class="card-meta"><span>${esc(o.payment)} · ${money(courierTotal(o))} so‘m</span><span>${Number.isFinite(o.distanceKm)?'Taxminiy '+o.distanceKm+' km':'Masofa kiritilmagan'}</span><span>${Number.isFinite(o.deliveryEtaMinutes)?'Taxminiy '+o.deliveryEtaMinutes+' daqiqa':'Yetkazish muddati kiritilmagan'}</span></div>${owned?`${courierDetails(o)}<ul class="order-items">${o.items.map(i=>`<li><b>${i.qty}×</b>${esc(i.name)}</li>`).join('')}</ul><p class="metric-note">Jami taom: ${o.items.reduce((sum,i)=>sum+i.qty,0)} dona</p><div class="notice">Mijoz izohi: ${esc(o.note||'Izoh yo‘q')}<br>Yetkazish izohi: ${esc(o.deliveryNote||'Izoh yo‘q')}</div><div class="card-actions">${courierPhone(b?.phone||courierState.profile.phone,'Restoran bilan aloqa')}${courierPhone(o.phone,'Mijoz bilan aloqa')}</div>`:''}${mode==='active'?courierTimeline(o):''}${o.delivery?.issue?`<div class="notice">${esc(issueTypes[o.delivery.issueType]||'Muammo')}: ${esc(o.delivery.issue)}</div>`:''}<div class="card-actions">${mode==='offer'?`<button class="btn primary" type="button" data-action="claim" data-id="${esc(o.id)}" ${!eligible?'disabled':''}>${!courierPerson()?.online?'Avval smenani boshlang':!deliveryReady(o)?'Yetkazish ma’lumoti yetishmaydi':'Qabul qilish'}</button>${courierButton('Rad qilish','decline',o.id,'danger')}`:mode==='active'?`${next?courierButton(next[0],next[1],o.id,'primary'):''}${courierButton('Muammo','issue',o.id,'danger')}${o.delivery.status==='assigned'?courierButton('Bekor qilish','cancel-delivery',o.id):courierButton('Restoranga qaytarish','return-delivery',o.id)}`:''}${owned?courierButton('Yo‘nalish','open-route',o.id):''}</div>${mode==='history'?`<p class="metric-note">${courierDate(o.delivery?.deliveredAt||o.delivery?.returnedAt||o.created)}</p>`:''}<p class="metric-note">Masofa va muddat sotuvchi kiritgan taxmin. Kuryer haqi mijozdan alohida olinmaydi.</p></article>`;};
courierOffers=function(){const declined=new Set((courierPerson().declined||[]).map(x=>x.orderId));const list=courierState.orders.filter(o=>o.status==='ready'&&!o.delivery&&!declined.has(o.id)&&(courierBranch==='all'||o.branch===courierBranch));return `<div class="page-title"><div><h1>Yangi buyurtmalar</h1><p class="subtitle">Manzil, taxminiy masofa, haq va to‘lov turini ko‘rib qabul qiling.</p></div>${courierButton('+ Demo buyurtma','demo','','soft')}</div>${!courierPerson().online?'<div class="online-hint">Buyurtma olish uchun smenani boshlang.</div>':''}<div class="filter-row"><select id="courier-branch" aria-label="Filial"><option value="all">Barcha filiallar</option>${courierState.branches.map(b=>`<option value="${esc(b.id)}" ${courierBranch===b.id?'selected':''}>${esc(b.name)}</option>`).join('')}</select>${courierButton('Yangilash','refresh')}</div>${list.length?`<div class="courier-grid">${list.map(o=>courierCard(o,'offer')).join('')}</div>`:courierEmpty('Hozircha yangi takliflar yo‘q. Demo buyurtma yaratib sinab ko‘ring.')}`;};
function courierHome(){const c=courierPerson(),active=courierActiveOrders(courierState,courierId);return `<section class="route-hero"><div><span class="tag">${workLabels[courierWork(c)]}</span><h1>Salom, ${esc(c.name.split(' ')[0])}!</h1><p>Bugungi yetkazmalar, daromad va ish holatingiz bir joyda.</p>${courierWorkButtons()}</div><div class="hero-bike" aria-hidden="true">🚲</div></section>${courierStats()}<div class="page-title"><div><h1>Faol yetkazma</h1><p class="subtitle">${active.length?'Navbatdagi bosqichni belgilang.':'Sizda faol yetkazma yo‘q.'}</p></div>${courierButton('Yangi buyurtmalar','nav','offers','primary')}</div>${active.length?`<div class="courier-grid">${active.map(o=>courierCard(o,'active')).join('')}</div>`:courierEmpty('Smenani boshlang va yangi takliflardan buyurtma tanlang.')}<div class="quick-links">${[['work','Ish jadvali','calendar'],['results','Natijalar','star'],['help','Yordam va muammolar','help']].map(([id,label,ico])=>`<button class="panel" type="button" data-action="nav" data-id="${id}">${icon(ico)}<strong>${label}</strong><span>↗</span></button>`).join('')}</div>`;}
let courierRouteId='';
function courierRoute(){const owned=courierState.orders.filter(o=>o.delivery?.courierId===courierId);const o=owned.find(o=>o.id===courierRouteId)||courierActiveOrders(courierState,courierId)[0]||owned[0];if(!o)return courierEmpty('Yo‘nalish uchun avval buyurtma oling.');courierRouteId=o.id;const b=courierBranchInfo(o.branch);return `<div class="page-title"><div><h1>Xarita va yo‘nalish</h1><p class="subtitle">Jonli GPS ulanmagan. Yo‘lni xarita ilovasida oching.</p></div></div><div class="filter-row"><select id="courier-route-order" aria-label="Yo‘nalish buyurtmasi">${owned.map(x=>`<option value="${esc(x.id)}" ${x.id===o.id?'selected':''}>#${esc(x.id.slice(0,12))}</option>`).join('')}</select></div><div class="route-map panel"><div class="route-art" aria-hidden="true"><b>R</b><i></i><b>M</b></div><div class="two-col"><div><span class="tag">Restoran</span><h2>${esc(b?.name||'—')}</h2><p>${esc(b?.address||'Manzil kiritilmagan')}</p>${courierDirection(b?.address,'Restoranga yo‘l')}${courierPhone(b?.phone||courierState.profile.phone,'Restoran')}</div><div><span class="tag success">Mijoz</span><h2>${esc(o.customer)}</h2><p>${esc(o.deliveryAddress||'Manzil kiritilmagan')}</p>${courierDirection(o.deliveryAddress,'Mijozga yo‘l',b?.address)}${courierPhone(o.phone,'Mijoz')}</div></div>${courierDetails(o)}<p class="metric-note">Masofa: ${Number.isFinite(o.distanceKm)?o.distanceKm+' km (taxminiy)':'kiritilmagan'}. Sxema haqiqiy xarita yoki geolokatsiya emas.</p></div>`;}
function courierWorkView(){const c=courierPerson(),shifts=[...(c.shifts||[])].reverse();return `<div class="page-title"><div><h1>Ish jadvali</h1><p class="subtitle">Smenani boshlash, tugatish va tanaffusni qayd etish.</p></div></div><div class="panel"><span class="tag">${workLabels[courierWork(c)]}</span>${courierWorkButtons()}<p class="metric-note">Faol buyurtma bo‘lsa, avval uni yetkazing yoki qaytarish oqimini yakunlang.</p></div><form id="courier-schedule" class="panel"><h2>Ishlash hududi va transport</h2>${courierField('Ishlash hududi','area',c.area||'','text','required maxlength="100"')}<div class="field"><label for="work-vehicle">Transport</label><select id="work-vehicle" name="vehicle">${['Velosiped','Skuter','Avtomobil','Piyoda'].map(v=>`<option ${c.vehicle===v?'selected':''}>${v}</option>`).join('')}</select></div><div class="form-error" role="alert"></div><button class="btn primary" type="submit">Saqlash</button></form><div class="panel table-wrap"><h2>Smenalar tarixi</h2><table><thead><tr><th>BOSHLANISH</th><th>TUGASH</th><th>TANAFFUS</th><th>HUDUD</th></tr></thead><tbody>${shifts.map(x=>`<tr><td>${courierDate(x.startedAt)}</td><td>${x.endedAt?courierDate(x.endedAt):'Davom etmoqda'}</td><td>${Math.round((x.breaks||[]).reduce((sum,b)=>sum+(b.endedAt||Date.now())-b.startedAt,0)/60000)} daq.</td><td>${esc(x.area)}</td></tr>`).join('')}</tbody></table>${shifts.length?'':'<p class="metric-note">Hali smena boshlanmagan.</p>'}</div>`;}
function courierAllHistory(){const delivered=courierHistory(courierState,courierId).map(o=>({id:'done:'+o.id,status:'delivered',at:o.delivery.deliveredAt,order:o})),returns=courierState.orders.filter(o=>o.delivery?.courierId===courierId&&o.delivery.status==='returned').map(o=>({id:'return:'+o.id,status:'returned',at:o.delivery.returnedAt,order:o})),archive=(courierState.courierArchive||[]).filter(e=>e.courierId===courierId);return [...delivered,...returns,...archive].sort((a,b)=>b.at-a.at);}
function courierHistoryRows(){return courierAllHistory().filter(e=>e.at>=courierSince()&&(!courierFromDate||e.at>=new Date(courierFromDate+'T00:00:00').getTime())&&(!courierToDate||e.at<new Date(courierToDate+'T00:00:00').getTime()+86400000)&&(courierHistoryStatus==='all'||e.status===courierHistoryStatus)&&`${e.order.id} ${e.order.customer} ${e.reason||''}`.toLowerCase().includes(courierHistoryQuery.toLowerCase())&&(courierMinFee===''||(e.order.delivery?.fee??e.order.deliveryFee??0)>=Number(courierMinFee))&&(courierMaxFee===''||(e.order.delivery?.fee??e.order.deliveryFee??0)<=Number(courierMaxFee)));}
function courierHistoryTable(){const rows=courierHistoryRows();return `<div class="panel table-wrap"><table><thead><tr><th>BUYURTMA</th><th>SANA</th><th>HOLAT</th><th>TAKLIF HAQI</th><th>HISOBLANGAN HAQ</th><th>SABAB</th></tr></thead><tbody>${rows.map(e=>`<tr><td><strong>#${esc(e.order.id.slice(0,12))}</strong><br>${esc(e.order.customer)}</td><td>${courierDate(e.at)}</td><td><span class="tag ${e.status==='delivered'?'success':'warning'}">${terminalLabels[e.status]}</span></td><td>${money(e.order.delivery?.fee??e.order.deliveryFee??0)}</td><td>${money(e.status==='delivered'?e.order.delivery.fee:0)}</td><td>${esc(e.reason||e.order.delivery?.returnReason||'—')}</td></tr>`).join('')}</tbody></table>${rows.length?'':'<p class="empty">Filtrlarga mos yetkazmalar yo‘q.</p>'}</div>`;}
courierHistoryView=function(){return `<div class="page-title"><div><h1>Yetkazmalar tarixi</h1><p class="subtitle">Yakunlangan, bekor qilingan, qaytarilgan va rad etilgan takliflar.</p></div>${courierButton('CSV yuklash','export-history')}</div>${courierPeriodFilter()}<div class="filter-row"><label class="history-date">Sanadan<input id="courier-from-date" type="date" aria-label="Boshlanish sanasi" value="${courierFromDate}"></label><label class="history-date">Sanagacha<input id="courier-to-date" type="date" aria-label="Tugash sanasi" value="${courierToDate}"></label><input id="courier-history-query" aria-label="Buyurtma qidirish" placeholder="Buyurtma yoki mijoz" value="${esc(courierHistoryQuery)}"><select id="courier-history-status" aria-label="Yetkazma holati"><option value="all">Barcha holatlar</option>${Object.entries(terminalLabels).map(([v,t])=>`<option value="${v}" ${courierHistoryStatus===v?'selected':''}>${t}</option>`).join('')}</select><input id="courier-min-fee" type="number" min="0" placeholder="Haq: dan" aria-label="Minimal haq" value="${courierMinFee}"><input id="courier-max-fee" type="number" min="0" placeholder="Haq: gacha" aria-label="Maksimal haq" value="${courierMaxFee}"></div><div id="courier-history-results">${courierHistoryTable()}</div>`;};
courierEarnings=function(){const list=courierDone(),since=courierSince(),extras=(courierState.courierExtras||[]).filter(e=>e.courierId===courierId&&e.at>=since),ledger=(courierState.courierLedger||[]).filter(e=>e.courierId===courierId&&e.at>=since),income=courierIncome(courierState,courierId),fees=list.reduce((sum,o)=>sum+o.delivery.fee,0);return `<div class="page-title"><div><h1>Daromad va hisob-kitob</h1><p class="subtitle">Yetkazma haqi, bonus, choychaqa va naqd hisob alohida.</p></div>${courierButton('Demo yozuv qo‘shish','money-record','','primary')}</div>${courierPeriodFilter()}<div class="stats">${[['Yetkazish haqi',fees],['Bonus',extras.filter(e=>e.type==='bonus').reduce((s,e)=>s+e.amount,0)],['Choychaqa',extras.filter(e=>e.type==='tip').reduce((s,e)=>s+e.amount,0)],['Davrdagi to‘lov qaydlari',ledger.filter(e=>e.type==='payout').reduce((s,e)=>s+e.amount,0)]].map(([t,n])=>`<div class="stat"><span class="stat-top">${t}</span><strong>${money(n)} <small>so‘m</small></strong></div>`).join('')}</div><div class="two-col"><div class="panel"><h2>Daromad qoldig‘i — barcha vaqt</h2><div class="summary-line"><span>Haq + bonus + choychaqa − to‘lov qaydlari</span><strong>${money(income.balance)} so‘m</strong></div><p class="metric-note">Haqiqiy bank balansi emas.</p></div><div class="panel"><h2>Mijozdan olingan naqd — barcha vaqt</h2><div class="summary-line"><span>Qabul qilingan</span><strong>${money(income.cash)}</strong></div><div class="summary-line"><span>Topshirish qaydlari</span><strong>${money(income.handed)}</strong></div><div class="summary-line"><span>Topshirilishi kerak</span><strong>${money(income.cashDue)}</strong></div></div></div><div class="notice">Barcha bonus, choychaqa va to‘lov yozuvlari qo‘lda kiritiladigan demo hisob. Pul o‘tkazish bajarilmaydi. Naqd buyurtma puli kuryer daromadiga qo‘shilmaydi.</div><div class="panel table-wrap"><h2>Yetkazishlar va qo‘shimcha daromadlar</h2><table><thead><tr><th>SANA</th><th>YOZUV</th><th>BUYURTMA</th><th>SUMMA</th></tr></thead><tbody>${[...list.map(o=>({at:o.delivery.deliveredAt,label:'Yetkazish haqi',orderId:o.id,amount:o.delivery.fee})),...extras.map(e=>({...e,label:e.type==='bonus'?'Bonus (demo)':'Choychaqa (demo)'}))].sort((a,b)=>b.at-a.at).map(e=>`<tr><td>${courierDate(e.at)}</td><td>${e.label}</td><td>#${esc(e.orderId.slice(0,12))}</td><td>${money(e.amount)}</td></tr>`).join('')}</tbody></table></div><div class="panel table-wrap"><h2>To‘lovlar va naqd topshirish tarixi</h2><table><thead><tr><th>SANA</th><th>TUR</th><th>SUMMA</th><th>HOLAT</th></tr></thead><tbody>${ledger.sort((a,b)=>b.at-a.at).map(e=>`<tr><td>${courierDate(e.at)}</td><td>${e.type==='cash'?'Naqd topshirish':'Daromad to‘lovi'}</td><td>${money(e.amount)}</td><td><span class="tag">Demo qayd</span></td></tr>`).join('')}</tbody></table>${ledger.length?'':'<p class="empty">To‘lov qaydlari yo‘q.</p>'}</div>`;};
function courierResults(){const list=courierDone(),timed=list.filter(o=>Number.isFinite(o.delivery.dueAt)),average=list.length?Math.round(list.reduce((s,o)=>s+o.delivery.deliveredAt-o.delivery.assignedAt,0)/list.length/60000):null,onTime=timed.filter(o=>o.delivery.deliveredAt<=o.delivery.dueAt).length,ids=new Set(list.map(o=>o.id)),ratings=(courierState.reviews||[]).filter(r=>ids.has(String(r.order))&&Number.isInteger(r.courierRating)&&r.courierRating>=1&&r.courierRating<=5);return `<div class="page-title"><div><h1>Natijalar</h1><p class="subtitle">Faqat qayd etilgan vaqtlar va kuryerga berilgan baholar.</p></div></div>${courierPeriodFilter()}<div class="stats">${[['Yetkazmalar soni',list.length,'ta'],['O‘rtacha yetkazish',average??'—','daq.'],['O‘z vaqtida',timed.length?Math.round(onTime/timed.length*100)+'%':'—',''],['Mijoz bahosi',ratings.length?(ratings.reduce((sum,r)=>sum+r.courierRating,0)/ratings.length).toFixed(1):'—','/ 5']].map(([t,v,u])=>`<div class="stat"><span class="stat-top">${t}</span><strong>${v} <small>${u}</small></strong></div>`).join('')}</div><div class="panel"><h2>Hisoblash asoslari</h2><p class="metric-note">Yetkazish vaqti — qabul qilishdan mijozga topshirishgacha. Muddati qayd etilgan yetkazmalar: ${timed.length}/${list.length}. Kuryer baholari: ${ratings.length}. Restoran baholari kuryer reytingiga qo‘shilmaydi. Mijoz bahosi olinadigan ilova hali ulanmagan.</p>${ratings.map(r=>`<div class="summary-line"><span>#${esc(r.order)} · ${esc(r.name)}</span><strong>★ ${r.courierRating}</strong></div>`).join('')}</div>`;}
function courierHelp(){const active=courierActiveOrders(courierState,courierId);return `<div class="page-title"><div><h1>Yordam va muammolar</h1><p class="subtitle">Muammoni buyurtmaga biriktirib saqlang.</p></div></div><div class="issue-grid">${Object.entries(issueTypes).map(([id,t])=>`<button type="button" class="panel issue-tile" data-action="help-issue" data-id="${id}">${icon(id==='vehicle'?'settings':'help')}<strong>${t}</strong><small>${active.length?'Faol buyurtmada belgilash':'Avval faol buyurtma kerak'}</small></button>`).join('')}</div><div class="notice">Xabar shu brauzerda owner va sotuvchi panelida ko‘rinadi. Dispetcher, tezkor yordam yoki tashqi xizmatga xabar yuborilmaydi.</div>${active.filter(o=>o.delivery.issue).map(o=>`<div class="panel"><h2>#${esc(o.id.slice(0,12))}</h2><p>${esc(issueTypes[o.delivery.issueType]||'Muammo')}</p><p>${esc(o.delivery.issue)}</p><span class="tag">Qayd etilgan · ${courierDate(o.delivery.issueAt)}</span></div>`).join('')}`;}
var courierBaseProfile=courierProfile;
courierProfile=function(){const prefs=courierPerson().preferences||{};return courierBaseProfile()+`<form id="courier-preferences" class="panel"><h2>Til va bildirishnomalar</h2><div class="field"><label for="courier-language">Til</label><select id="courier-language" name="language"><option value="uz" ${prefs.language!=='ru'?'selected':''}>O‘zbekcha</option><option value="ru" ${prefs.language==='ru'?'selected':''}>Русский — asosiy boshqaruv</option></select><small>Ruscha rejim asosiy menyu va amallarni tarjima qiladi. Manzillar, izohlar va batafsil yordam matnlari asl holida qoladi.</small></div><label class="check"><input name="sound" type="checkbox" ${prefs.sound?'checked':''}>Yangi taklif uchun ovoz</label><label class="check"><input name="notifications" type="checkbox" ${prefs.notifications!==false?'checked':''}>Panel ichida bildirishnoma</label>${courierButton('Ovozni sinash','test-courier-sound')}<p class="metric-note">Brauzer push xizmati ulanmagan. Ovoz sahifa bilan muloqotdan keyin ishlaydi.</p><div class="form-error" role="alert"></div><button type="submit" class="btn primary">Saqlash</button></form>`;};
var courierBaseRender=courierRender;
courierRender=function(){if(['home','route','work','results','help'].includes(courierPage)){const selected=courierPage;courierPage='offers';courierBaseRender();courierPage=selected;if(courierPerson()&&!courierError){$('#main').innerHTML=({home:courierHome,route:courierRoute,work:courierWorkView,results:courierResults,help:courierHelp})[selected]();$('#sidebar').querySelectorAll('[data-action="nav"]').forEach(b=>{b.classList.toggle('active',b.dataset.id===selected);if(b.dataset.id===selected)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');});const crumb=$('#topbar .crumb strong');if(crumb)crumb.textContent=courierNav.find(n=>n[0]===selected)[1];}}else courierBaseRender();if(courierPerson()){const top=$('#topbar');top.innerHTML=top.innerHTML.replace(courierPerson().online?'● Liniyada':'● Liniyada emas',workLabels[courierWork(courierPerson())]).replace('Dam olish</button>','Smenani tugatish</button>').replace('Liniyaga chiqish</button>','Smenani boshlash</button>');}courierLocalize();};
const courierRussian={'Bosh ekran':'Главная','Yangi buyurtmalar':'Новые заказы','Faol yetkazma':'Активная доставка','Xarita va yo‘nalish':'Карта и маршрут','Daromad va hisob-kitob':'Доходы и расчёты','Ish jadvali':'График работы','Yetkazmalar tarixi':'История доставок','Natijalar':'Результаты','Yordam va muammolar':'Помощь и проблемы','Profil va sozlamalar':'Профиль и настройки','Ishdaman':'На смене','Tanaffusdaman':'На перерыве','Ishda emasman':'Не на смене','Smenani boshlash':'Начать смену','Smenani tugatish':'Закончить смену','Qabul qilish':'Принять','Rad qilish':'Отклонить','Restorandaman':'Я в ресторане','Buyurtmani oldim':'Заказ получен','Mijozga yetib keldim':'Я у клиента','Yetkazildi':'Доставлено','Bekor qilish':'Отмена','Tasdiqlash':'Подтвердить','Saqlash':'Сохранить','Yangilash':'Обновить','Muammo':'Проблема','Restoranga qaytarish':'Вернуть в ресторан','Yo‘nalish':'Маршрут','Restoranga yo‘l':'Маршрут в ресторан','Mijozga yo‘l':'Маршрут к клиенту','Barcha holatlar':'Все статусы','Barcha filiallar':'Все филиалы','Yakunlangan':'Завершено','Bekor qilingan':'Отменено','Restoranga qaytarilgan':'Возвращено в ресторан','Rad etilgan taklif':'Отклонённое предложение','Mijoz bilan aloqa':'Связаться с клиентом','Restoran bilan aloqa':'Связаться с рестораном','Bonus':'Бонус','Choychaqa':'Чаевые','Kuryer profili':'Профиль курьера','Ism va familiya':'Имя и фамилия','Telefon':'Телефон','Transport':'Транспорт','Ishlash hududi':'Зона работы','Til va bildirishnomalar':'Язык и уведомления','Til':'Язык','Bugun':'Сегодня','So‘nggi 7 kun':'Последние 7 дней','So‘nggi 30 kun':'Последние 30 дней','Barcha vaqt':'За всё время','CSV yuklash':'Скачать CSV','Restoran kechikishi':'Ресторан задерживает заказ','Mijoz javob bermasligi':'Клиент не отвечает','Noto‘g‘ri manzil':'Неверный адрес','Transport muammosi':'Проблема с транспортом','Shikastlangan buyurtma':'Заказ повреждён','Boshqa muammo':'Другая проблема'};
function courierLocalize(){if(!document.createTreeWalker)return;document.documentElement.lang=courierPerson()?.preferences?.language||'uz';if(document.documentElement.lang!=='ru')return;for(const root of [$('#sidebar'),$('#topbar'),$('#main'),$('#dialog')]){const walker=document.createTreeWalker(root,4);let node;while(node=walker.nextNode()){const text=node.nodeValue.trim();if(courierRussian[text])node.nodeValue=node.nodeValue.replace(text,courierRussian[text]);}}}
function courierIssueModal(id,type='other'){courierModal('Muammoni belgilash',`<div class="field"><label for="issue-type">Muammo turi</label><select id="issue-type" name="issueType">${Object.entries(issueTypes).map(([v,t])=>`<option value="${v}" ${type===v?'selected':''}>${t}</option>`).join('')}</select></div><div class="field"><label for="issue-text">Izoh</label><textarea id="issue-text" name="text" required minlength="3" maxlength="500"></textarea></div><p class="metric-note">Owner va sotuvchi panelida demo qayd sifatida ko‘rinadi.</p>`,'issue-form',id);courierLocalize();}
function courierMoneyModal(){const list=courierHistory(courierState,courierId);courierModal('Demo hisob-kitob yozuvi',`<div class="notice">Bu forma faqat demo jurnaliga yozadi. Haqiqiy pul o‘tkazilmaydi.</div><div class="field"><label for="money-type">Yozuv turi</label><select id="money-type" name="type"><option value="bonus">Bonus</option><option value="tip">Choychaqa</option><option value="payout">Daromad to‘lovi qaydi</option><option value="cash">Naqd topshirish qaydi</option></select></div><div class="field"><label for="money-order">Bonus/choychaqa uchun yetkazilgan buyurtma</label><select id="money-order" name="orderId"><option value="">Buyurtmani tanlang</option>${list.map(o=>`<option value="${esc(o.id)}">#${esc(o.id.slice(0,12))}</option>`).join('')}</select></div>${courierField('Summa (so‘m)','amount','','number','required min="1" max="10000000" step="1"')}`,'courier-money');}
function courierHistoryExport(){const rows=[['Buyurtma','Sana','Holat','Taklif haqi','Hisoblangan haq','Sabab'],...courierHistoryRows().map(e=>[e.order.id,new Date(e.at).toISOString(),terminalLabels[e.status],e.order.delivery?.fee??e.order.deliveryFee??0,e.status==='delivered'?e.order.delivery.fee:0,e.reason||e.order.delivery?.returnReason||''])];const csv='\uFEFF'+rows.map(r=>r.map(v=>'"'+String(/^[=+@\-]/.test(String(v))?"'"+v:v).replace(/"/g,'""')+'"').join(';')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='lazzat-kuryer-tarix.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;const {action,id}=b.dataset;if(!['work-working','work-break','work-offline','arrive-restaurant','arrive-customer','decline','cancel-delivery','return-delivery','help-issue','issue','open-route','money-record','export-history','test-courier-sound'].includes(action))return;e.preventDefault();e.stopImmediatePropagation();if(courierBusy)return;try{if(action==='test-courier-sound'){courierOfferSound();return;}if(action.startsWith('work-')){await courierRun('work','',{status:action.slice(5)});courierRender();return;}if(['arrive-restaurant','arrive-customer'].includes(action)){await courierRun(action,id);courierRender();return;}if(action==='open-route'){courierRouteId=id;courierPage='route';courierRender();return;}if(action==='money-record'){courierMoneyModal();return;}if(action==='export-history'){courierHistoryExport();return;}if(action==='help-issue'){const o=courierActiveOrders(courierState,courierId)[0];if(!o)throw Error('Avval faol buyurtma kerak.');courierIssueModal(o.id,id);return;}if(action==='issue'){courierIssueModal(id);return;}const operation=action==='decline'?'decline':action==='cancel-delivery'?'cancel':'return';courierModal(operation==='decline'?'Taklifni rad qilish':operation==='cancel'?'Yetkazishni bekor qilish':'Restoranga qaytarish',`<div class="field"><label for="terminal-reason">Sabab</label><textarea id="terminal-reason" name="reason" required minlength="3" maxlength="500"></textarea></div>${operation==='return'?'<label class="check"><input type="checkbox" name="returnConfirmed" required>Buyurtmani restoranga qaytarib topshirdim</label><p class="metric-note">Restoran savdosi va owner foyda hisobidan chiqariladi. Kuryer haqi hisoblanmaydi. Mijozga pul qaytarish tizimi hali ulanmagan.</p>':'<p class="metric-note">Buyurtma boshqa kuryerlarga taklif etilishi mumkin.</p>'}`,'courier-terminal',id);$('#dialog form').dataset.operation=operation;courierLocalize();}catch(error){courierToast(error.message);}},true);
document.addEventListener('submit',async e=>{const form=e.target;if(!['courier-schedule','courier-preferences','courier-money','courier-terminal'].includes(form.id))return;e.preventDefault();e.stopImmediatePropagation();if(courierBusy||!form.reportValidity())return;const f=new FormData(form);let action,payload;if(form.id==='courier-schedule'){action='schedule';payload={area:f.get('area'),vehicle:f.get('vehicle')};}if(form.id==='courier-preferences'){action='preferences';payload={language:f.get('language'),sound:f.has('sound'),notifications:f.has('notifications')};}if(form.id==='courier-money'){const type=f.get('type');action=['bonus','tip'].includes(type)?'extra':'ledger';payload={type,amount:f.get('amount'),orderId:f.get('orderId')};}if(form.id==='courier-terminal'){action=form.dataset.operation;payload={reason:f.get('reason'),returnConfirmed:f.has('returnConfirmed')};}try{await courierRun(action,form.dataset.id,payload);courierClose();courierRender();courierToast('O‘zgarishlar saqlandi.');}catch(error){form.querySelector('.form-error').textContent=error.message;}},true);
document.addEventListener('change',e=>{if(e.target.id==='courier-from-date'){courierFromDate=e.target.value;courierPeriod='all';courierRender();}if(e.target.id==='courier-to-date'){courierToDate=e.target.value;courierPeriod='all';courierRender();}if(e.target.id==='courier-route-order'){courierRouteId=e.target.value;courierRender();}if(e.target.id==='courier-history-status'){courierHistoryStatus=e.target.value;courierRender();}});
document.addEventListener('input',e=>{if(!['courier-history-query','courier-min-fee','courier-max-fee'].includes(e.target.id))return;if(e.target.id==='courier-history-query')courierHistoryQuery=e.target.value;if(e.target.id==='courier-min-fee')courierMinFee=e.target.value;if(e.target.id==='courier-max-fee')courierMaxFee=e.target.value;$('#courier-history-results').innerHTML=courierHistoryTable();courierLocalize();});
var courierAudio;
function courierOfferSound(){try{const Audio=window.AudioContext||window.webkitAudioContext;if(!Audio)return;courierAudio??=new Audio();if(courierAudio.state==='suspended')courierAudio.resume();const osc=courierAudio.createOscillator(),gain=courierAudio.createGain();osc.connect(gain);gain.connect(courierAudio.destination);osc.frequency.value=740;gain.gain.setValueAtTime(.08,courierAudio.currentTime);gain.gain.exponentialRampToValueAtTime(.001,courierAudio.currentTime+.3);osc.start();osc.stop(courierAudio.currentTime+.3);}catch{}}
let courierSeenOffers=new Set(courierState?.orders.filter(o=>o.status==='ready'&&!o.delivery).map(o=>o.id)||[]);
window.addEventListener('storage',e=>{if(e.key!==COURIER_STORE||!courierPerson())return;const offers=courierState.orders.filter(o=>o.status==='ready'&&!o.delivery),fresh=offers.some(o=>!courierSeenOffers.has(o.id));courierSeenOffers=new Set(offers.map(o=>o.id));if(fresh&&courierWork(courierPerson())==='working'){const prefs=courierPerson().preferences||{};if(prefs.notifications!==false)courierToast('Yangi buyurtma mavjud. Takliflarni ko‘ring.');if(prefs.sound)courierOfferSound();}});
courierPage='home';courierRender();
